const response = $input.first().json.response;
const source = $input.first().json.source;
const confidence = $input.first().json.confidence;

// These are invalid sources — agent answered 
// from its own knowledge, not from Supabase
const invalidSources = [
  "no_source_found",

  "parse_error",
  null,
  undefined,
  ""
];

const sourceIsValid = !invalidSources.includes(source);

if (sourceIsValid) {
  // Citation exists — safe to send to patient
  return [{
    json: {
      finalResponse: response,
      citationValid: true,
      source: source,
      confidence: confidence
    }
  }];
} else {
  // No citation — override with safe fallback
  return [{
    json: {
      finalResponse: "I want to make sure I give you " +
        "accurate information and I'm not confident I " +
        "have the right details for that. Please visit " +
        "nhs.uk or call NHS 111 on 111.",
      citationValid: false,
      source: source,
      confidence: confidence
    }
  }];
}

const raw = $input.first().json.output;

let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match[0]);
} catch(e) {
  parsed = {
    response: raw,
    confidence: 0.8,
    source: "parse_error"
  };
}

return [{
  json: {
    response: parsed.response || raw,
    confidence: parsed.confidence ?? 0.8,
    source: parsed.source || 'no_source_needed',
    originalMessage: $('Webhook').first().json.body.message,
    sessionId: $('Webhook').first().json.body.sessionId
  }
}];

const raw = $input.first().json.output;

let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match[0]);
} catch(e) {
  parsed = {
    response: raw,
    name: null,
    phone: null,
    postcode: null,
    registration_complete: false
  };
}

return [{
  json: {
    response: parsed.response,
    name: parsed.name,
    phone: parsed.phone,
    address: parsed.address,
    registration_complete: parsed.registration_complete,
    sessionId: $('Webhook').first().json.body.sessionId,
    message: $('Webhook').first().json.body.message
  }
}];
